import * as React from "react";
import LoaderButton from "@/registry/default/ui/loaderButton";

export default function LoaderButtonVariants() {
    const [isLoading, setIsLoading] = React.useState<boolean>(false);

    async function onSubmit(event: React.SyntheticEvent) {
        event.preventDefault();
        setIsLoading(true);

        setTimeout(() => {
            setIsLoading(false);
        }, 3000);
    }

    return (
        <>
            <div className="px-4 py-10 w-full grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-6">
                <LoaderButton
                    buttonVariant={"default"}
                    onClick={onSubmit}
                    isLoading={isLoading}
                    className="my-class"
                >
                    Loader Button
